-- Generated from scripts/grade9-term1-learning-content.cjs. Do not hand-edit.
-- Additive Sprint 4 v3 explicit distractor-feedback corrections. v1/v2 remain retained for audit and attempt history.

with authored(item_code,skill_code,grade,prompt,answer_config,solution,reasoning_classification,cognitive_level) as (
values
  ('Q.G9.S4.PRACTICE.REAL.01', 'G9-NUM-REAL-IRRATIONAL', 'Grade 9', 'Which number is irrational?', '{"type":"multiple_choice","options":{"A":"√20","B":"0.25","C":"−7","D":"3/5"},"correct_option":"A","distractor_explanations":{"B":"0.25 is rational because it equals 1/4. A terminating decimal can be written as a fraction of integers.","C":"−7 is rational because it equals −7/1. A negative sign does not make a number irrational.","D":"3/5 is already a ratio of two integers, so it is rational. An irrational number cannot be expressed in that form."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '20 is not a perfect square, so √20 cannot be written as a ratio of integers. The other choices are rational.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.REAL.02', 'G9-NUM-REAL-IRRATIONAL', 'Grade 9', 'Classify √121.', '{"type":"multiple_choice","options":{"A":"Not a real number","B":"A rational integer","C":"An irrational number","D":"A negative integer"},"correct_option":"B","distractor_explanations":{"A":"√121 is real because 121 is positive. Find the number whose square is 121: it is 11.","C":"√121 is not irrational: 121 is the perfect square 11 × 11, so its root is the integer 11.","D":"The principal square root √121 is 11, not −11. The root symbol names the non-negative root."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '√121 = 11. It is a natural number, an integer and therefore rational.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.REAL.03', 'G9-NUM-REAL-IRRATIONAL', 'Grade 9', 'Why is 0.333… rational?', '{"type":"multiple_choice","options":{"A":"It is close to zero","B":"It contains a decimal point","C":"It is equal to 1/3","D":"It has infinitely many digits"},"correct_option":"C","distractor_explanations":{"A":"Being close to zero does not decide whether a number is rational. The repeating decimal 0.333… equals 1/3.","B":"A decimal point alone does not prove a number rational. This decimal is rational because its repeating pattern equals 1/3.","D":"Having infinitely many digits is not enough; non-repeating decimals can be irrational. Here the digits repeat, giving 1/3."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'A recurring decimal has a fractional form. Here 0.333… = 1/3, so it is rational.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.REAL.04', 'G9-NUM-REAL-IRRATIONAL', 'Grade 9', 'Which statement is correct about √(1/4)?', '{"type":"multiple_choice","options":{"A":"It is irrational because 1/4 is not an integer","B":"It equals 1/16 because both parts are squared","C":"It is not real","D":"It is rational because √(1/4) = 1/2"},"correct_option":"D","distractor_explanations":{"A":"1/4 need not be an integer for its root to be rational. Since (1/2)² = 1/4, √(1/4) = 1/2.","B":"Taking a square root reverses squaring; it does not square the numerator and denominator. Test (1/2)² to find the root.","C":"1/4 is non-negative, so it has a real square root. The principal root is the non-negative fraction 1/2."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The principal square root of 1/4 is 1/2 because (1/2)² = 1/4. A rational radicand need not be an integer.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.HCF-LCM.01', 'G9-NUM-WHOLE-HCF-LCM', 'Grade 9', 'What is the prime factorisation of 84?', '{"type":"multiple_choice","options":{"A":"2 × 3 × 7","B":"2³ × 3 × 7","C":"2² × 3² × 7","D":"2² × 3 × 7"},"correct_option":"D","distractor_explanations":{"A":"2 × 3 × 7 equals 42, so one factor of 2 is missing. Divide 84 by 2 twice before using 3 and 7.","B":"2³ × 3 × 7 equals 168, so this includes one too many factors of 2. Check that the factors multiply back to 84.","C":"2² × 3² × 7 equals 252, so the factor 3 has been used twice. Prime-factor products must equal the original number."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '84 = 4 × 21 = 2² × 3 × 7.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.HCF-LCM.02', 'G9-NUM-WHOLE-HCF-LCM', 'Grade 9', 'Find the HCF of 30 and 45.', '{"type":"multiple_choice","options":{"A":"15","B":"5","C":"10","D":"90"},"correct_option":"A","distractor_explanations":{"B":"5 is common, but it is not the highest common factor. Both 30 and 45 are also divisible by 15.","C":"10 divides 30 but not 45, so it cannot be a common factor. Check divisibility in both numbers.","D":"90 is the product-related LCM, not a factor of 30 or 45. An HCF must divide each number exactly."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '30 = 2 × 3 × 5 and 45 = 3² × 5. The common factors are 3 and 5, so the HCF is 15.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.HCF-LCM.03', 'G9-NUM-WHOLE-HCF-LCM', 'Grade 9', 'Two buses arrive together at the starting time, then every 12 and 18 minutes. How many minutes later do they next arrive together?', '{"type":"multiple_choice","options":{"A":"216 minutes","B":"36 minutes","C":"6 minutes","D":"30 minutes"},"correct_option":"B","distractor_explanations":{"A":"216 is a common multiple, but not the least one. The question asks for the next time after starting together: 36 minutes.","C":"6 is the HCF of 12 and 18, not their next shared multiple. A future shared arrival must be a multiple of both intervals.","D":"30 is not divisible by 12 or 18, so the buses would not both arrive then. List common multiples until the first one."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Starting together means the next shared arrival is the LCM. LCM(12,18) = 36.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.HCF-LCM.04', 'G9-NUM-WHOLE-HCF-LCM', 'Grade 9', 'A learner says the HCF of 16 and 24 is 384. What is the correction?', '{"type":"multiple_choice","options":{"A":"HCF is 384, because numbers are multiplied","B":"HCF is 16, because it is the smaller number","C":"HCF is 8, the greatest factor common to both","D":"HCF is 40, because factors are added"},"correct_option":"C","distractor_explanations":{"A":"384 is the product of 16 and 24, not a shared divisor. HCF means the greatest number that divides both exactly.","B":"The smaller number is not automatically a common factor: 24 is not divisible by 16. Check which factors both numbers share.","D":"Adding 16 and 24 gives 40, but a common factor must divide both numbers. Test divisors such as 8 instead."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '16 = 2⁴ and 24 = 2³ × 3. The common part is 2³ = 8.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.RATIO-RATE.01', 'G9-NUM-RATIO-RATE', 'Grade 9', 'Simplify 18 : 24.', '{"type":"multiple_choice","options":{"A":"9 : 12","B":"42 : 1","C":"3 : 4","D":"6 : 8 : 2"},"correct_option":"C","distractor_explanations":{"A":"9 : 12 is equivalent to 18 : 24, but it is not fully simplified. Divide both parts by their HCF, 3.","B":"42 : 1 changes the relationship rather than simplifying it. A ratio is simplified by dividing every part by the same factor.","D":"6 : 8 : 2 has introduced a third part, so it no longer compares the same two quantities. Divide both original parts by 6."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The HCF of 18 and 24 is 6. Divide both parts: 18 ÷ 6 : 24 ÷ 6 = 3 : 4.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.RATIO-RATE.02', 'G9-NUM-RATIO-RATE', 'Grade 9', 'A taxi travels 150 km in 3 hours. What is its average speed?', '{"type":"multiple_choice","options":{"A":"153 km/h","B":"450 km/h","C":"47 km/h","D":"50 km/h"},"correct_option":"D","distractor_explanations":{"A":"153 adds the distance and time instead of finding a rate. Average speed is distance divided by time: 150 ÷ 3.","B":"450 multiplies distance by time, but speed is kilometres per one hour. Divide 150 km by 3 hours.","C":"47 subtracts the time from the distance. To find a unit rate, divide 150 by 3."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Speed = distance ÷ time = 150 ÷ 3 = 50 km/h.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.RATIO-RATE.03', 'G9-NUM-RATIO-RATE', 'Grade 9', 'Paint is mixed red : white = 2 : 5. If 6 cups are red, how many cups are white?', '{"type":"multiple_choice","options":{"A":"15 cups","B":"11 cups","C":"30 cups","D":"5 cups"},"correct_option":"A","distractor_explanations":{"B":"11 adds the two ratio parts rather than scaling the white part. Red changes from 2 to 6 by a factor of 3.","C":"30 scales white by 6 instead of using the ratio scale factor. Since 2 becomes 6, multiply 5 by 3.","D":"5 is the white part in the original ratio, before scaling. The red amount has tripled, so white must also triple."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Red changes from 2 to 6, so multiply by 3. White is 5 × 3 = 15 cups.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.RATIO-RATE.04', 'G9-NUM-RATIO-RATE', 'Grade 9', 'A learner claims that 4 : 6 and 10 : 15 are not equivalent. Which explanation correctly evaluates the claim?', '{"type":"multiple_choice","options":{"A":"The claim is incorrect because all ratios are equivalent","B":"The claim is incorrect: 4 : 6 = 2 : 3 and 10 : 15 = 2 : 3","C":"The claim is correct because the numbers in each ratio are different","D":"The claim is correct because only ratios already in lowest terms can be equivalent"},"correct_option":"B","distractor_explanations":{"A":"The claim is incorrect here, but not all ratios are equivalent. Equivalence requires the same simplified ratio, which is 2 : 3.","C":"Different-looking numbers can name the same ratio. Simplify 4 : 6 and 10 : 15 before comparing their multiplicative relationship.","D":"A ratio need not already be simplified to be equivalent. Both ratios simplify to 2 : 3."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Simplify each ratio by its own common factor: 4 : 6 ÷ 2 = 2 : 3 and 10 : 15 ÷ 5 = 2 : 3. Both describe the same multiplicative relationship, so the learner’s claim is incorrect.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.PROPORTION.01', 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Grade 9', 'Five notebooks cost R40. What do eight cost at the same price?', '{"type":"multiple_choice","options":{"A":"R320","B":"R13","C":"R64","D":"R48"},"correct_option":"C","distractor_explanations":{"A":"R320 multiplies the total R40 by 8 without first finding one notebook’s price. Use R40 ÷ 5, then multiply by 8.","B":"R13 is not the cost of eight notebooks at the constant rate. Find the R8 unit price, then scale it to eight.","D":"R48 uses R6 per notebook, but R40 shared by 5 notebooks is R8 each. Multiply the unit price by 8."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'One notebook costs R40 ÷ 5 = R8. Eight cost 8 × R8 = R64.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.PROPORTION.02', 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Grade 9', 'Eight taps fill a tank in 6 hours. How long would 12 identical taps take?', '{"type":"multiple_choice","options":{"A":"9 hours","B":"18 hours","C":"6 hours","D":"4 hours"},"correct_option":"D","distractor_explanations":{"A":"9 hours treats more taps as taking more time. With the same tank, more identical taps mean fewer hours.","B":"18 hours multiplies both quantities as if the relationship were direct. Keep the tap-hour product 8 × 6 constant.","C":"6 hours ignores the extra four taps. Divide the fixed 48 tap-hours by 12 taps."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The work is 8 × 6 = 48 tap-hours. 48 ÷ 12 = 4 hours.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.PROPORTION.03', 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Grade 9', 'Which situation is inverse proportion?', '{"type":"multiple_choice","options":{"A":"For a fixed trip, higher speed means less travel time","B":"More loaves cost more at one price","C":"More litres give a higher water bill","D":"More pages mean more printing"},"correct_option":"A","distractor_explanations":{"B":"More loaves costing more is direct proportion: both quantities increase together. Inverse proportion has a fixed product or task.","C":"A higher bill for more litres is direct proportion at a constant price. It does not show one quantity decreasing as the other increases.","D":"More pages requiring more printing is direct, not inverse. Look for a fixed trip or task where one quantity rises while the other falls."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'For the same distance, speed × time is fixed. Increasing speed decreases time.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.PROPORTION.04', 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Grade 9', 'A learner doubles workers and doubles days. What error was made?', '{"type":"multiple_choice","options":{"A":"They should add workers and days","B":"They treated an inverse relationship as direct","C":"They simplified the ratio too far","D":"They forgot a decimal point"},"correct_option":"B","distractor_explanations":{"A":"Adding workers and days does not model a fixed job. Multiply workers by days, then keep that product constant.","C":"The error is not about simplifying a ratio. For one fixed job, workers and days should change in opposite directions.","D":"No decimal placement causes the problem. Doubling workers should halve days to keep total worker-days unchanged."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'For the same job, doubling workers halves the time. The worker-day total stays constant.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.FINANCE.01', 'G9-NUM-FINANCIAL-APPLICATIONS', 'Grade 9', 'What is 7% commission on R3 000?', '{"type":"multiple_choice","options":{"A":"R21","B":"R2 790","C":"R700","D":"R210"},"correct_option":"D","distractor_explanations":{"A":"R21 treats 7% as 0.007 or uses the wrong place value. Convert 7% to 0.07 before multiplying R3 000.","B":"R2 790 is the amount left after subtracting commission, not the commission itself. Calculate 7% of R3 000.","C":"R700 treats 7% as 7/30 or a much larger percentage. Use 7 ÷ 100 = 0.07, then multiply."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '7% = 0.07. R3 000 × 0.07 = R210.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.FINANCE.02', 'G9-NUM-FINANCIAL-APPLICATIONS', 'Grade 9', 'A bike rents for R80 per day and requires a refundable R50 deposit paid at collection. What is paid upfront for 3 days, and what is the net rental cost after the deposit is returned?', '{"type":"multiple_choice","options":{"A":"R290 upfront; R240 net rental","B":"R390 upfront; R390 net rental","C":"R240 upfront; R240 net rental","D":"R290 upfront; R290 net rental"},"correct_option":"A","distractor_explanations":{"B":"R390 counts the R50 deposit three times and never returns it. Add the deposit once to R240, then remove it from net cost.","C":"R240 is the rental fee only; the refundable R50 must still be paid upfront. Add it once at collection.","D":"R290 is paid upfront, but the R50 deposit is refundable. After it is returned, only the R240 rental fee remains."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The 3-day rental fee is 3 × R80 = R240. The R50 deposit is added once at collection, so R290 is paid upfront; because it is refundable, the net rental cost after return is R240.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.FINANCE.03', 'G9-NUM-FINANCIAL-APPLICATIONS', 'Grade 9', 'R1 500 grows by 8% compound interest for two years. What is the balance?', '{"type":"multiple_choice","options":{"A":"R1 620.80","B":"R1 749.60","C":"R1 620.00","D":"R1 740.00"},"correct_option":"B","distractor_explanations":{"A":"R1 620.80 applies an incorrect small second increase. Calculate 8% of R1 620, then add it to that balance.","C":"R1 620.00 is the balance after only one 8% increase. Compound interest applies the second 8% to R1 620.","D":"R1 740.00 adds two simple 8% increases to the original amount. Compound interest uses the increased balance in year two."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Year 1: 1500 × 1.08 = 1620. Year 2: 1620 × 1.08 = 1749.60.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.FINANCE.04', 'G9-NUM-FINANCIAL-APPLICATIONS', 'Grade 9', 'Why is compound interest greater than simple interest after two positive years?', '{"type":"multiple_choice","options":{"A":"The original balance is ignored","B":"Interest is subtracted first","C":"Second-year interest is earned on the increased balance","D":"The percentage doubles automatically"},"correct_option":"C","distractor_explanations":{"A":"The original balance remains part of the accumulated balance. What changes is that first-year interest also earns interest.","B":"Interest is added to grow the balance, not subtracted. The second calculation uses the balance after year-one interest.","D":"The percentage stays the same; its base changes. In year two, the same rate is applied to the larger balance."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Compound interest adds year-one interest to the balance before calculating year two.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.INTEGER-OPS.01', 'G9-NUM-INTEGERS-OPERATIONS', 'Grade 9', 'Calculate −8 + 13.', '{"type":"multiple_choice","options":{"A":"−21","B":"−5","C":"21","D":"5"},"correct_option":"D","distractor_explanations":{"A":"−21 combines the magnitudes as if both numbers were negative. Adding +13 moves 13 units right from −8.","B":"−5 subtracts 13 from 8 rather than adding a positive number. Compare magnitudes: 13 is five more than 8.","C":"21 adds magnitudes but ignores the negative starting value. Start at −8 and move right 13 to reach 5."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Starting at −8 and adding 13 gives 5.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.INTEGER-OPS.02', 'G9-NUM-INTEGERS-OPERATIONS', 'Grade 9', 'Calculate (−7) × 6.', '{"type":"multiple_choice","options":{"A":"−42","B":"42","C":"−13","D":"13"},"correct_option":"A","distractor_explanations":{"B":"42 has the right magnitude but misses the sign rule. A negative factor times a positive factor gives a negative product.","C":"−13 adds −7 and 6 instead of multiplying. First multiply the magnitudes, then apply the different-sign rule.","D":"13 adds the magnitudes and ignores multiplication. Calculate 7 × 6, then use the negative sign from unlike factors."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The signs differ, so the product is negative. 7 × 6 = 42.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.INTEGER-OPS.03', 'G9-NUM-INTEGERS-OPERATIONS', 'Grade 9', 'Calculate 18 ÷ [3 + (−6)].', '{"type":"multiple_choice","options":{"A":"−3","B":"−6","C":"6","D":"0"},"correct_option":"B","distractor_explanations":{"A":"−3 is the bracket value, not the completed division. After finding −3, divide 18 by it.","C":"6 uses the magnitude of the divisor but ignores its negative sign. Evaluate the bracket first: 3 + (−6) is −3.","D":"0 may come from adding 3 and −6 incorrectly. The bracket is −3, and 18 divided by −3 is not zero."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Evaluate the bracket: 3 + (−6) = −3. Then 18 ÷ −3 = −6.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.INTEGER-OPS.04', 'G9-NUM-INTEGERS-OPERATIONS', 'Grade 9', 'Why is −4 − 7 equal to −11?', '{"type":"multiple_choice","options":{"A":"Only 7 is negative","B":"All subtraction answers are negative","C":"Subtracting 7 moves 7 units left from −4","D":"The signs cancel"},"correct_option":"C","distractor_explanations":{"A":"7 is positive in −4 − 7; the subtraction operation changes the movement direction. Use a number line to move left.","B":"Subtraction can give positive, zero, or negative results. Here it is negative because starting at −4 and moving left gives −11.","D":"Signs do not cancel in subtraction this way. Subtracting positive 7 means moving left seven units from −4."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'On a number line start at −4 and move seven units left, reaching −11.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.POWERS-ROOTS.01', 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Grade 9', 'What is (−5)²?', '{"type":"multiple_choice","options":{"A":"25","B":"−25","C":"−10","D":"10"},"correct_option":"A","distractor_explanations":{"B":"−25 keeps a negative sign after squaring. The whole negative number is squared, and two negative factors multiply to a positive.","C":"−10 doubles −5 instead of squaring it. Squaring means multiplying the base by itself: (−5) × (−5).","D":"10 doubles the magnitude rather than squaring. Expand (−5)² as (−5) × (−5) to get a positive product."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '(−5)² = (−5) × (−5) = 25.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.POWERS-ROOTS.02', 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Grade 9', 'What is ∛(−216)?', '{"type":"multiple_choice","options":{"A":"36","B":"−6","C":"6","D":"−36"},"correct_option":"B","distractor_explanations":{"A":"36 confuses a square-related value with a cube root. Test −6 × −6 × −6 instead.","C":"6 cubed is positive 216, not −216. A cube root of a negative number must be negative.","D":"−36 is not a cube root; cubing it would be far from −216. Find the number that multiplied by itself three times gives −216."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '(−6) × (−6) × (−6) = −216.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.POWERS-ROOTS.03', 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Grade 9', 'Evaluate −3².', '{"type":"multiple_choice","options":{"A":"−6","B":"6","C":"−9","D":"9"},"correct_option":"C","distractor_explanations":{"A":"−6 doubles −3 instead of applying the exponent. Calculate 3² first, then apply the outside negative sign.","B":"6 changes the expression into doubling and also loses the leading negative. Without brackets, −3² means −(3 × 3).","D":"9 treats −3 as the bracketed base, but there are no brackets. The exponent applies to 3, then the leading negative remains."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The exponent applies to 3 first: −3² = −(3²) = −9.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.POWERS-ROOTS.04', 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Grade 9', 'Why is √64 not ±8?', '{"type":"multiple_choice","options":{"A":"Square roots have no value","B":"Both signs are always written","C":"64 has only one square root equation","D":"√ means the principal non-negative root"},"correct_option":"D","distractor_explanations":{"A":"√64 does have a value: 8 × 8 = 64. The root symbol is defined to select the principal non-negative root.","B":"± is used when solving x² = 64, not when evaluating √64. The radical symbol alone means the non-negative root.","C":"The equation x² = 64 has two solutions, 8 and −8. The notation √64 still names just the principal value 8."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The equation x² = 64 has ±8 solutions, but the symbol √64 is defined as the principal root 8.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.EXP-LAWS.01', 'G9-EXP-LAWS-EXTENDED', 'Grade 9', 'Simplify a⁴ × a³.', '{"type":"multiple_choice","options":{"A":"a⁷","B":"a¹²","C":"a¹","D":"7a"},"correct_option":"A","distractor_explanations":{"B":"a¹² multiplies the exponents, which is for a power of a power. With a⁴ × a³, count factors and add exponents.","C":"a¹ subtracts exponents as if dividing. Multiplication of the same base requires 4 + 3.","D":"7a treats exponents as ordinary coefficients. The base stays a and the total number of factors is a⁷."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The bases match, so add exponents: 4 + 3 = 7.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.EXP-LAWS.02', 'G9-EXP-LAWS-EXTENDED', 'Grade 9', 'For y ≠ 0, simplify y⁹ ÷ y⁴.', '{"type":"multiple_choice","options":{"A":"1/y⁵","B":"y⁵","C":"y¹³","D":"y³⁶"},"correct_option":"B","distractor_explanations":{"A":"1/y⁵ would be y⁻⁵, not y⁹ ÷ y⁴. Cancel the four denominator factors from the nine numerator factors.","C":"y¹³ adds exponents as in multiplication. Division of equal non-zero bases cancels four factors, leaving 9 − 4.","D":"y³⁶ multiplies exponents, which is for a power of a power. Here divide y⁹ by y⁴ and subtract exponents."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Because y ≠ 0, the quotient is defined. For division with the same base, subtract: 9 − 4 = 5.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.EXP-LAWS.03', 'G9-EXP-LAWS-EXTENDED', 'Grade 9', 'Simplify (m²n³)².', '{"type":"multiple_choice","options":{"A":"m⁴n⁹","B":"m²n⁶","C":"m⁴n⁶","D":"m⁴n⁵"},"correct_option":"C","distractor_explanations":{"A":"n⁹ adds exponents instead of multiplying for a power of a power. Square n³ by using 3 × 2.","B":"n⁶ is correct, but m² must also be squared. Multiply both inner exponents by the outer 2.","D":"m⁴ is correct, but n³ squared multiplies 3 by 2, giving n⁶. Apply the outside power to every factor."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Apply the outer power to each factor: m^(2×2)n^(3×2).', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.EXP-LAWS.04', 'G9-EXP-LAWS-EXTENDED', 'Grade 9', 'A learner writes x² + x³ = x⁵. What is correct?', '{"type":"multiple_choice","options":{"A":"The answer is always x⁵","B":"Add the bases instead","C":"Subtract the exponents","D":"The product law applies to multiplication, not addition"},"correct_option":"D","distractor_explanations":{"A":"x⁵ would follow from multiplying x² and x³, but the operation here is addition. Exponent laws do not combine unlike addends.","B":"The bases are both x, so adding bases does not simplify x² + x³. The terms have different exponents and remain separate.","C":"Subtracting exponents is a division rule, not an addition rule. Keep x² + x³ as written."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'x² and x³ are unlike terms, so they do not combine through an exponent law.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.EXP-ZERO-NEGATIVE.01', 'G9-EXP-NEGATIVE-SCI', 'Grade 9', 'What is 9⁰?', '{"type":"multiple_choice","options":{"A":"Undefined","B":"1","C":"0","D":"9"},"correct_option":"B","distractor_explanations":{"A":"9⁰ is defined because the base is non-zero. The undefined case to avoid is 0⁰, not 9⁰.","C":"0 confuses a zero exponent with a zero base. For non-zero 9, the zero-exponent rule gives 9⁰ = 1.","D":"9 keeps the base but ignores the exponent. A non-zero base raised to zero equals 1."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Any non-zero number to exponent zero equals 1.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.EXP-ZERO-NEGATIVE.02', 'G9-EXP-NEGATIVE-SCI', 'Grade 9', 'What is 10⁻²?', '{"type":"multiple_choice","options":{"A":"100","B":"−0.01","C":"0.01","D":"−100"},"correct_option":"C","distractor_explanations":{"A":"100 ignores the negative exponent. A negative exponent means reciprocal, so use 1 divided by 100.","B":"−0.01 adds a negative sign that is not in the base. The negative exponent changes position, not the sign.","D":"−100 treats the negative exponent as a negative answer and reverses the reciprocal. First write 10⁻² as 1/10²."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '10⁻² = 1/10² = 1/100 = 0.01.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.EXP-ZERO-NEGATIVE.03', 'G9-EXP-NEGATIVE-SCI', 'Grade 9', 'Which expression equals 1/p⁵?', '{"type":"multiple_choice","options":{"A":"−p⁵","B":"p⁵","C":"1/5p","D":"p⁻⁵"},"correct_option":"D","distractor_explanations":{"A":"−p⁵ changes the sign of the expression, but it is not a reciprocal. A negative exponent means 1 divided by p⁵.","B":"p⁵ has the reciprocal backwards. Move p⁵ to the denominator by giving it exponent −5.","C":"1/5p divides by 5 and then multiplies by p; it is not 1 divided by p⁵. Keep p as the base with exponent −5."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'By definition, p⁻⁵ = 1/p⁵ for p ≠ 0.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.EXP-ZERO-NEGATIVE.04', 'G9-EXP-NEGATIVE-SCI', 'Grade 9', 'Why is 0⁰ not used in the zero-exponent rule?', '{"type":"multiple_choice","options":{"A":"The quotient-law argument would divide 0 by 0","B":"Zero has no powers","C":"It must equal 1","D":"It must equal 0"},"correct_option":"A","distractor_explanations":{"B":"Zero can be raised to positive powers, such as 0² = 0. The issue is specifically the undefined form 0⁰.","C":"The non-zero rule a⁰ = 1 cannot be applied with a = 0. Its quotient-law argument would require division by zero.","D":"0⁰ is not set to 0 by the zero-base pattern. The usual zero-exponent proof fails because it would divide 0 by 0."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The rule a⁰ comes from a¹ ÷ a¹, which needs a non-zero base.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.SCI-NOTATION.01', 'G9-EXP-SCI-NOTATION-EXTENSION', 'Grade 9', 'Write 72 000 in scientific notation.', '{"type":"multiple_choice","options":{"A":"7.2 × 10⁴","B":"72 × 10³","C":"7.2 × 10³","D":"0.72 × 10⁵"},"correct_option":"A","distractor_explanations":{"B":"72 × 10³ has the right value but 72 is not between 1 and 10. Shift the decimal once more and increase the exponent.","C":"7.2 is correctly sized, but 10³ moves the decimal only three places to 7 200. Count four places for 72 000.","D":"0.72 × 10⁵ has the right value but the coefficient is below 1. Standard notation needs 1 ≤ |a| < 10."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Move the decimal four places left: 72 000 = 7.2 × 10⁴.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.SCI-NOTATION.02', 'G9-EXP-SCI-NOTATION-EXTENSION', 'Grade 9', 'What is 3.6 × 10³ in ordinary notation?', '{"type":"multiple_choice","options":{"A":"0.0036","B":"3 600","C":"360","D":"36 000"},"correct_option":"B","distractor_explanations":{"A":"0.0036 treats the positive exponent as a negative one. A positive power of 10 makes the number larger.","C":"360 moves the decimal only two places. The exponent 3 means multiply 3.6 by 1 000.","D":"36 000 shifts the decimal four places, not three. Starting at 3.6, move it three places right."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '10³ = 1000, so 3.6 × 1000 = 3600.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.SCI-NOTATION.03', 'G9-EXP-SCI-NOTATION-EXTENSION', 'Grade 9', 'Write −0.0042 in standard scientific notation.', '{"type":"multiple_choice","options":{"A":"−4.2 × 10³","B":"−0.42 × 10⁻²","C":"−4.2 × 10⁻³","D":"4.2 × 10⁻³"},"correct_option":"C","distractor_explanations":{"A":"−4.2 × 10³ is −4 200, much larger than −0.0042. Moving the decimal right for a small number needs a negative exponent.","B":"−0.42 × 10⁻² equals −0.0042, but −0.42 is not a standard coefficient. Shift it to −4.2 and adjust the exponent.","D":"4.2 × 10⁻³ has the right magnitude but loses the original negative sign. Keep the sign in the coefficient."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Keep the negative sign. Move the decimal three places right to get −4.2, so use exponent −3; |−4.2| is between 1 and 10.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.SCI-NOTATION.04', 'G9-EXP-SCI-NOTATION-EXTENSION', 'Grade 9', 'Why is 45 × 10⁵ not standard scientific notation?', '{"type":"multiple_choice","options":{"A":"The exponent must be negative","B":"Scientific notation cannot use 10⁵","C":"45 is too small","D":"|45| is not less than 10"},"correct_option":"D","distractor_explanations":{"A":"Positive exponents are valid for large numbers. The issue is the coefficient 45, whose absolute value is not less than 10.","B":"10⁵ is allowed in scientific notation. Standard form restricts the coefficient, not whether a positive exponent is used.","C":"45 is too large for the coefficient range 1 ≤ |a| < 10. Rewrite it as 4.5 × 10⁶ instead."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'For any nonzero number in standard form, 1 ≤ |a| < 10. Here |45| is too large; rewrite it as 4.5 × 10⁶.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.PATTERN-STRUCTURE.01', 'G9-PAT-NUMERIC-STRUCTURE', 'Grade 9', 'What is the first difference of 11, 16, 21, 26, …?', '{"type":"multiple_choice","options":{"A":"−5","B":"5","C":"11","D":"10"},"correct_option":"B","distractor_explanations":{"A":"−5 reverses the subtraction order. The pattern increases, so use later term minus earlier term to get +5.","C":"11 is the first term, not the difference. Subtract consecutive terms: 16 − 11 and 21 − 16.","D":"10 does not match the increase from 11 to 16. Calculate the difference by subtraction, not by combining non-adjacent terms."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '16 − 11 = 5, and the same change continues.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.PATTERN-STRUCTURE.02', 'G9-PAT-NUMERIC-STRUCTURE', 'Grade 9', 'Extend 4, 10, 16, … by two terms.', '{"type":"multiple_choice","options":{"A":"26, 36","B":"18, 20","C":"22, 28","D":"20, 24"},"correct_option":"C","distractor_explanations":{"A":"26, 36 changes the step size after the first new term. Add 6 each time to preserve the linear pattern.","B":"18, 20 does not continue the +6 difference. Compare 10 − 4 and 16 − 10 before extending.","D":"20, 24 uses an increase of 4, but the given terms increase by 6. Continue the same first difference."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The first difference is 6, so add 6 twice.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.PATTERN-STRUCTURE.03', 'G9-PAT-NUMERIC-STRUCTURE', 'Grade 9', 'Which statement shows a linear pattern?', '{"type":"multiple_choice","options":{"A":"Its terms are all even","B":"Its ratio is constant","C":"It starts at zero","D":"Its first differences are constant"},"correct_option":"D","distractor_explanations":{"A":"Even terms alone do not ensure a linear pattern; their differences could change. A linear sequence has a constant first difference.","B":"A constant ratio identifies a geometric pattern, not generally a linear one. Check successive differences instead.","C":"A linear pattern can start at any value. What matters is that the increase or decrease stays constant."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Constant first differences identify a linear pattern.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.PATTERN-STRUCTURE.04', 'G9-PAT-NUMERIC-STRUCTURE', 'Grade 9', 'A table has T1 = 7, T2 = 12, T3 = 17. What is T8?', '{"type":"multiple_choice","options":{"A":"42","B":"37","C":"47","D":"52"},"correct_option":"A","distractor_explanations":{"B":"37 adds the difference six times from 7, but reaching T8 requires seven increases. Count the jumps from term 1 to term 8.","C":"47 uses too many increases or the wrong starting point. Use T8 = 7 + 5(8 − 1).","D":"52 adds 5 nine times rather than seven. From T1 to T8 there are exactly seven equal steps."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The difference is 5. From T1 to T8 there are seven increases: 7 + 7×5 = 42.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.NTH-TERM.01', 'G9-PAT-GENERAL-RULE', 'Grade 9', 'Find the nth term of 3, 7, 11, …', '{"type":"multiple_choice","options":{"A":"4n − 1","B":"4n + 3","C":"3n + 1","D":"n + 3"},"correct_option":"A","distractor_explanations":{"B":"4n + 3 gives 7 when n = 1, not the first term 3. Keep the difference 4, then choose a constant that fits n = 1.","C":"3n + 1 gives the wrong constant difference of 3. The sequence rises by 4 each time.","D":"n + 3 increases by only 1 per term. The coefficient of n must match the first difference, 4."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Difference is 4. At n=1, 4+c=3, so c=−1.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.NTH-TERM.02', 'G9-PAT-GENERAL-RULE', 'Grade 9', 'For Tn = 5n + 2, find T6.', '{"type":"multiple_choice","options":{"A":"13","B":"32","C":"30","D":"37"},"correct_option":"B","distractor_explanations":{"A":"13 appears to substitute the wrong n-value. The question asks for T6, so use n = 6.","C":"30 uses 5 × 6 but omits the +2 in the rule. Substitute both parts of Tn = 5n + 2.","D":"37 adds 2 to the wrong multiple of 5. Calculate 5 × 6 first, then add 2 once."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Substitute n=6: 5(6)+2=32.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.NTH-TERM.03', 'G9-PAT-GENERAL-RULE', 'Grade 9', 'Why should you test an nth-term rule using n = 2?', '{"type":"multiple_choice","options":{"A":"It makes c equal zero","B":"It removes the need for n = 1","C":"It checks that the rule fits more than one term","D":"It changes the first difference"},"correct_option":"C","distractor_explanations":{"A":"The constant c is set by fitting a term, not automatically made zero by testing n = 2. Testing provides another check.","B":"n = 1 is still useful to find the constant. n = 2 confirms the same rule works beyond one term.","D":"Testing n = 2 does not change the pattern. It checks whether the proposed rule gives the actual second term."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'A second test catches a rule that only happens to fit the first term.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.NTH-TERM.04', 'G9-PAT-GENERAL-RULE', 'Grade 9', 'A learner gives Tn = 3n + 8 for 8, 11, 14, … . What is correct?', '{"type":"multiple_choice","options":{"A":"It should be 8n + 3","B":"It should be 3n","C":"The learner rule is correct","D":"It should be 3n + 5"},"correct_option":"D","distractor_explanations":{"A":"8n + 3 uses the first term as the difference, but the sequence increases by 3. Use coefficient 3 and fit the constant.","B":"3n has the correct difference but gives 3 at n = 1, not 8. Add a constant so the first term fits.","C":"3n + 8 gives 11 for n = 1, so it does not match the first term 8. Test a rule at n = 1."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The difference is 3. At n=1, 3+c=8, so c=5.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.VISUAL-PATTERNS.01', 'G9-PAT-GEOMETRIC-VISUAL', 'Grade 9', 'How many matchsticks are needed for 4 joined squares in a row?', '{"type":"multiple_choice","options":{"A":"12","B":"16","C":"10","D":"13"},"correct_option":"D","distractor_explanations":{"A":"12 uses 3 matchsticks per square but omits the first square’s extra side. A joined row follows 3n + 1.","B":"16 counts four sides for every square and double-counts shared sides. Each extra square adds only 3 matchsticks.","C":"10 treats the first square as if it also adds only 3 sides. Start with 4, then add 3 for each of the next squares."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'M = 3n+1. For n=4, M=13.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.VISUAL-PATTERNS.02', 'G9-PAT-GEOMETRIC-VISUAL', 'Grade 9', 'Which rule fits a pattern beginning 5, 8, 11, …?', '{"type":"multiple_choice","options":{"A":"3n + 2","B":"3n + 5","C":"5n + 3","D":"n + 4"},"correct_option":"A","distractor_explanations":{"B":"3n + 5 has the right difference but gives 8 at n = 1, not 5. Test the rule using the first figure.","C":"5n + 3 uses a difference of 5, but the pattern increases by 3. The coefficient must match the first difference.","D":"n + 4 increases by only 1 each term. The sequence rises by 3, so its n coefficient must be 3."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Difference is 3. At n=1, 3+c=5, so c=2.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.VISUAL-PATTERNS.03', 'G9-PAT-GEOMETRIC-VISUAL', 'Grade 9', 'Why does a joined-square row use 3n + 1 instead of 4n?', '{"type":"multiple_choice","options":{"A":"Squares only need three sides","B":"Each added square shares one side","C":"The first square has no sides","D":"n is always one"},"correct_option":"B","distractor_explanations":{"A":"A single square has four sides. In a joined row, a shared side is counted once rather than requiring only three sides per square.","C":"The first square has four sides. The reduction comes because each later square shares one side with its neighbour.","D":"n counts the number of squares and changes from figure to figure. The +1 comes from the first unshared side, not from n being fixed."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The n−1 shared sides mean the total is 4n−(n−1)=3n+1.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.VISUAL-PATTERNS.04', 'G9-PAT-GEOMETRIC-VISUAL', 'Grade 9', 'A tile pattern has figure 1 = 6 and adds 4 tiles each figure. What is figure 7?', '{"type":"multiple_choice","options":{"A":"34","B":"42","C":"30","D":"28"},"correct_option":"C","distractor_explanations":{"A":"34 uses seven increases after figure 1 instead of six. Count the gaps between figure 1 and figure 7.","B":"42 multiplies 6 by 7 as if the total were scaled, but the pattern adds 4 tiles each new figure.","D":"28 makes only five increases of 4 from figure 1. Figure 7 is six steps after figure 1."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Tn=6+4(n−1). T7=6+4×6=30.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-FACTORS.01', 'G8-NUM-WHOLE-PROPERTIES', 'Grade 8', 'Simplify 18 ÷ 3 + 4.', '{"type":"multiple_choice","options":{"A":"3","B":"22","C":"10","D":"2"},"correct_option":"C","distractor_explanations":{"A":"3 may be the divisor, but it is not the full expression’s value. Follow order of operations before adding.","B":"22 adds 18 and 4 before dividing, which changes the expression. Division comes before addition here.","D":"2 subtracts or divides in the wrong order. Do the division 18 ÷ 3 first, then add 4."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '18 ÷ 3 = 6, then 6 + 4 = 10.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-FACTORS.02', 'G8-NUM-WHOLE-PROPERTIES', 'Grade 8', 'Which is a factor of 36?', '{"type":"multiple_choice","options":{"A":"8","B":"10","C":"14","D":"9"},"correct_option":"D","distractor_explanations":{"A":"8 does not divide 36 exactly; 36 ÷ 8 leaves a remainder. A factor must divide with no remainder.","B":"10 is not a factor because 36 ÷ 10 is not whole. Test division to check a proposed factor.","C":"14 does not divide 36 exactly. Look for a number that makes a whole-number quotient, such as 9."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '36 ÷ 9 = 4 with no remainder.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-FACTORS.03', 'G8-NUM-WHOLE-PROPERTIES', 'Grade 8', 'Simplify 5 + 3 × 4.', '{"type":"multiple_choice","options":{"A":"17","B":"32","C":"20","D":"12"},"correct_option":"A","distractor_explanations":{"B":"32 adds 5 and 3 before multiplying by 4. Multiplication has priority, so calculate 3 × 4 first.","C":"20 multiplies 5 by 4 and ignores the 3. Follow the expression as written: only 3 is multiplied by 4.","D":"12 is the product 3 × 4, but the leading +5 still needs to be included."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Multiply 3×4 first, then add 5.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-FACTORS.04', 'G8-NUM-WHOLE-PROPERTIES', 'Grade 8', 'Why is 6 a common factor of 18 and 30?', '{"type":"multiple_choice","options":{"A":"It is a multiple of neither","B":"It divides both without a remainder","C":"It is their sum","D":"It is bigger than both"},"correct_option":"B","distractor_explanations":{"A":"Whether 6 is a multiple is not the definition of a common factor. Check 18 ÷ 6 and 30 ÷ 6.","C":"6 is not the sum of 18 and 30. It is common because both numbers can be divided by 6 with no remainder.","D":"6 is smaller than both numbers, and size alone does not make a factor. Test whether it divides each exactly."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '18 ÷ 6 = 3 and 30 ÷ 6 = 5, so 6 divides both numbers exactly.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-FRACTIONS.01', 'G8-NUM-FRACTIONS-OPERATIONS', 'Grade 8', 'Calculate 1/4 + 2/4.', '{"type":"multiple_choice","options":{"A":"3/4","B":"3/8","C":"2/8","D":"1/2"},"correct_option":"A","distractor_explanations":{"B":"3/8 adds the denominators, which is not allowed when they already match. Keep denominator 4 and add the numerators.","C":"2/8 changes both the numerator total and the common denominator. With fourths, 1 fourth plus 2 fourths is 3 fourths.","D":"1/2 is equivalent to 2/4, not 3/4. Add the numerators first, then simplify only if possible."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The denominators match, so add the numerators.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-FRACTIONS.02', 'G8-NUM-FRACTIONS-OPERATIONS', 'Grade 8', 'Write 3/5 with denominator 20.', '{"type":"multiple_choice","options":{"A":"8/20","B":"12/20","C":"3/20","D":"15/20"},"correct_option":"B","distractor_explanations":{"A":"8/20 does not keep the fraction’s value because 3 was not multiplied by 4. Make 5 into 20, then do the same to 3.","C":"3/20 changes only the denominator, so it is not equivalent to 3/5. Multiply numerator and denominator by 4.","D":"15/20 multiplies the numerator by 5 while the denominator is multiplied by 4. Use the same factor on both parts."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Multiply numerator and denominator by 4.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-FRACTIONS.03', 'G8-NUM-FRACTIONS-OPERATIONS', 'Grade 8', 'Calculate 2/3 − 1/6.', '{"type":"multiple_choice","options":{"A":"1/3","B":"1/18","C":"1/2","D":"1/6"},"correct_option":"C","distractor_explanations":{"A":"1/3 may come from using a denominator of 3, but 1/6 must be converted to a common denominator before subtraction.","B":"1/18 multiplies denominators, which is not the method for subtracting fractions. Use the common denominator 6.","D":"1/6 subtracts numerators without first changing 2/3 to sixths. Rewrite 2/3 as 4/6."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '2/3=4/6. 4/6−1/6=3/6=1/2.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-FRACTIONS.04', 'G8-NUM-FRACTIONS-OPERATIONS', 'Grade 8', 'Why is 2/4 equal to 1/2?', '{"type":"multiple_choice","options":{"A":"The denominators are added","B":"The numerator is smaller than the denominator","C":"Fractions cannot be simplified","D":"Dividing both numerator and denominator by 2 gives 1/2"},"correct_option":"D","distractor_explanations":{"A":"Adding denominators does not show equivalent fractions. Divide both numerator and denominator of 2/4 by the same number.","B":"Many proper fractions have a smaller numerator, but that does not prove they equal 1/2. Simplify 2/4 using a common factor.","C":"Fractions can be simplified when numerator and denominator share a factor. Divide both 2 and 4 by 2."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Divide numerator and denominator of 2/4 by the same non-zero number: 2÷2 / 4÷2 = 1/2.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-DECIMALS.01', 'G8-NUM-DECIMALS-OPERATIONS', 'Grade 8', 'Calculate 6.2 − 1.45.', '{"type":"multiple_choice","options":{"A":"5.25","B":"4.65","C":"4.85","D":"4.75"},"correct_option":"D","distractor_explanations":{"A":"5.25 misaligns place values during subtraction. Write 6.2 as 6.20, then subtract hundredths, tenths, and ones.","B":"4.65 subtracts digits without correctly borrowing across decimal places. Line up the decimal points before subtracting.","C":"4.85 has an incorrect tenths or hundredths subtraction. Use 6.20 − 1.45 with aligned columns."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Write 6.2 as 6.20, then subtract: 6.20 − 1.45 = 4.75.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-DECIMALS.02', 'G8-NUM-DECIMALS-OPERATIONS', 'Grade 8', 'Calculate 0.4 × 0.5.', '{"type":"multiple_choice","options":{"A":"0.2","B":"2","C":"0.02","D":"0.9"},"correct_option":"A","distractor_explanations":{"B":"2 ignores decimal places and is too large: multiplying two numbers below 1 should give a number below 1.","C":"0.02 places the decimal one position too far left. Four tenths times five tenths is twenty hundredths, or 0.20.","D":"0.9 adds 0.4 and 0.5 rather than multiplying. Estimate first: the product should be about one fifth."},"feedback_source":"explicitly_authored_v3"}'::jsonb, '4×5=20; two decimal places give 0.20.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-DECIMALS.03', 'G8-NUM-DECIMALS-OPERATIONS', 'Grade 8', 'A R12.50 item costs how much for 3?', '{"type":"multiple_choice","options":{"A":"R125.00","B":"R37.50","C":"R15.50","D":"R36.50"},"correct_option":"B","distractor_explanations":{"A":"R125.00 shifts the decimal point and is ten times too large. Keep cents when multiplying 12.50 by 3.","C":"R15.50 adds a small amount instead of multiplying the full price by 3. Multiply R12.50 three times.","D":"R36.50 has the right tens but an incorrect cents calculation. Add 12.50 + 12.50 + 12.50 carefully."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Multiply R12.50 by 3: 12.50 × 3 = 37.50, so the total is R37.50.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-DECIMALS.04', 'G8-NUM-DECIMALS-OPERATIONS', 'Grade 8', 'Why is estimating useful with decimals?', '{"type":"multiple_choice","options":{"A":"It removes units","B":"It makes all answers whole","C":"It can reveal a misplaced decimal point","D":"It replaces calculation"},"correct_option":"C","distractor_explanations":{"A":"Estimation still needs units, such as rand or kilometres. Its purpose is to spot unreasonable sizes or decimal placement.","B":"Estimates can be decimal values too. They help predict the size of an answer, not force it to be whole.","D":"Estimating checks whether a calculation is reasonable; it does not replace the exact calculation when an exact answer is needed."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'An answer near 20 for 0.4×0.5 is unreasonable; estimate catches it.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-INTEGERS.01', 'G8-NUM-INTEGERS-OPERATIONS', 'Grade 8', 'Calculate −9 + 4.', '{"type":"multiple_choice","options":{"A":"5","B":"−13","C":"13","D":"−5"},"correct_option":"D","distractor_explanations":{"A":"5 ignores that −9 has the greater magnitude. Starting at −9 and moving 4 right lands on −5.","B":"−13 treats +4 as another negative addend. Adding a positive moves toward zero, from −9 to −5.","C":"13 adds magnitudes but loses the sign of the larger magnitude. Compare 9 and 4, then keep the sign of −9."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Move four right from −9 to −5.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-INTEGERS.02', 'G8-NUM-INTEGERS-OPERATIONS', 'Grade 8', 'Calculate (−5) × (−3).', '{"type":"multiple_choice","options":{"A":"15","B":"−15","C":"−8","D":"8"},"correct_option":"A","distractor_explanations":{"B":"−15 has the right magnitude but the wrong sign. Two negative factors multiply to a positive result.","C":"−8 adds −5 and −3 instead of multiplying. Multiply the magnitudes first, then use the same-sign rule.","D":"8 adds magnitudes rather than multiplying. Calculate 5 × 3 and remember that matching negative signs give positive."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Same signs give positive; 5×3=15.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-INTEGERS.03', 'G8-NUM-INTEGERS-OPERATIONS', 'Grade 8', 'Calculate 7 − (−2).', '{"type":"multiple_choice","options":{"A":"−5","B":"9","C":"5","D":"−9"},"correct_option":"B","distractor_explanations":{"A":"−5 uses the difference of the magnitudes with an unsupported negative sign. Add 2 to 7 after rewriting the expression.","C":"5 treats subtracting −2 as subtracting positive 2. Rewrite 7 − (−2) as 7 + 2.","D":"−9 changes both signs and does not follow the subtraction rule. A double negative here becomes addition."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Subtracting −2 means add 2: 7+2=9.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-INTEGERS.04', 'G8-NUM-INTEGERS-OPERATIONS', 'Grade 8', 'Why is (−12) ÷ 3 negative?', '{"type":"multiple_choice","options":{"A":"Both numbers are negative","B":"12 is greater than 3","C":"The signs are different","D":"Division ignores signs"},"correct_option":"C","distractor_explanations":{"A":"Only −12 is negative; 3 is positive. The different signs explain why the quotient is negative.","B":"Magnitude comparison does not set the sign of a quotient. Check whether the two signs match or differ.","D":"Division does use signs. A negative divided by a positive has unlike signs, so the quotient is negative."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'A negative divided by a positive is negative.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-EXPONENTS.01', 'G8-EXP-LAWS-SCI', 'Grade 8', 'What is 2⁴?', '{"type":"multiple_choice","options":{"A":"16","B":"8","C":"6","D":"24"},"correct_option":"A","distractor_explanations":{"B":"8 is 2³, so it uses only three factors. The exponent 4 requires 2 × 2 × 2 × 2.","C":"6 multiplies the base by the exponent instead of using repeated multiplication. Write four factors of 2.","D":"24 may come from 2 × 3 × 4, but exponents repeat the base, not consecutive numbers. Multiply four 2s."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The exponent 4 means four factors: 2 × 2 × 2 × 2 = 16.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-EXPONENTS.02', 'G8-EXP-LAWS-SCI', 'Grade 8', 'Simplify x² × x⁵.', '{"type":"multiple_choice","options":{"A":"x³","B":"x⁷","C":"x¹⁰","D":"2x⁷"},"correct_option":"B","distractor_explanations":{"A":"x³ subtracts the exponents as if dividing. Multiplying x² and x⁵ gives seven factors of x.","C":"x¹⁰ multiplies exponents, which is for a power of a power. For multiplication of the same base, add 2 and 5.","D":"2x⁷ adds an unnecessary coefficient 2. The exponents add while the base remains x."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Same base product: add 2+5.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-EXPONENTS.03', 'G8-EXP-LAWS-SCI', 'Grade 8', 'What is the base in (−4)³?', '{"type":"multiple_choice","options":{"A":"4 only","B":"−3","C":"−4","D":"3"},"correct_option":"C","distractor_explanations":{"A":"The brackets include the negative sign in the base. The repeated factor is −4, not just 4.","B":"−3 combines the sign and exponent incorrectly. Read the expression: −4 is inside the brackets and 3 is outside.","D":"3 is the exponent, not the base. The base is the complete quantity being repeatedly multiplied."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Brackets make the complete signed number the base.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-EXPONENTS.04', 'G8-EXP-LAWS-SCI', 'Grade 8', 'Why is a³ × a² not a⁶?', '{"type":"multiple_choice","options":{"A":"Bases are added","B":"The base changes to 6","C":"It is always a⁶","D":"The exponents are added, not multiplied"},"correct_option":"D","distractor_explanations":{"A":"The bases stay a; they are not added. Count the total factors of a to see that exponents add.","B":"6 is not a new base. The base remains a and the exponents 3 and 2 combine by addition.","C":"a⁶ would result from multiplying exponents, not from multiplying powers with the same base. Use 3 + 2."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'There are 3+2 factors of a, giving a⁵.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-PATTERNS.01', 'G8-PAT-REPRESENT-RULE', 'Grade 8', 'What comes next: 9, 13, 17, …?', '{"type":"multiple_choice","options":{"A":"19","B":"20","C":"22","D":"21"},"correct_option":"D","distractor_explanations":{"A":"19 adds 2 instead of the constant difference 4. Compare 13 − 9 and 17 − 13.","B":"20 does not continue the +4 pattern. Add the same difference to 17.","C":"22 adds 5, not the established difference 4. Keep the change consistent from term to term."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'The constant difference is 4.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-PATTERNS.02', 'G8-PAT-REPRESENT-RULE', 'Grade 8', 'For Tn=2n+1, find T4.', '{"type":"multiple_choice","options":{"A":"9","B":"7","C":"8","D":"12"},"correct_option":"A","distractor_explanations":{"B":"7 may use n = 3 rather than n = 4. Substitute the requested value 4 into 2n + 1.","C":"8 doubles 4 but omits the +1 in the rule. Apply both operations in 2(4) + 1.","D":"12 adds or multiplies the rule incorrectly. Evaluate 2 × 4 first, then add 1 once."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Substitute n = 4: T4 = 2(4) + 1 = 9.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-PATTERNS.03', 'G8-PAT-REPRESENT-RULE', 'Grade 8', 'Which rule fits 4, 7, 10, …?', '{"type":"multiple_choice","options":{"A":"n + 3","B":"3n + 1","C":"3n + 4","D":"4n − 1"},"correct_option":"B","distractor_explanations":{"A":"n + 3 increases by only 1, not 3. Use 3n plus a constant that makes the first term 4.","C":"3n + 4 has the right difference but gives 7 at n = 1, not 4. Test the rule against the first term.","D":"4n − 1 changes by 4 each term, but the sequence changes by 3. The coefficient must match the difference."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'Difference is 3 and 3(1)+1=4.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-PATTERNS.04', 'G8-PAT-REPRESENT-RULE', 'Grade 8', 'Why test a rule at n=2?', '{"type":"multiple_choice","options":{"A":"It removes the difference","B":"All rules work at n=2","C":"It confirms another term matches","D":"It changes n into 1"},"correct_option":"C","distractor_explanations":{"A":"The common difference remains part of the pattern. Testing another n-value verifies that the rule preserves it.","B":"A wrong rule can fail at n = 2, so testing it is useful. Compare the predicted second term with the actual one.","D":"Testing n = 2 does not change n; it substitutes 2 to predict the second term. This checks the proposed rule."},"feedback_source":"explicitly_authored_v3"}'::jsonb, 'A second value can show whether a rule was fitted incorrectly.', 'mathematical_reasoning', 'complex')
)
insert into public.question_versions(question_item_id,version_number,review_status,activity_type,cognitive_level,representation,difficulty,reasoning_classification,calculator_policy,prompt,answer_config,solution,marks,material_change_note)
select item.id,3,'draft','guided_practice',authored.cognitive_level::public.caps_cognitive_level,'symbolic',case when authored.reasoning_classification='mathematical_reasoning' then 3 else 2 end,authored.reasoning_classification,'not_allowed',authored.prompt,authored.answer_config,authored.solution,1,'Sprint 4 v3: replaces inferred distractor feedback with individually authored misconception-specific feedback. Versions 1 and 2 remain immutable for audit and historical attempts.'
from authored
join public.curriculum_versions curriculum on curriculum.grade=authored.grade and curriculum.is_active
join public.question_items item on item.item_code=authored.item_code and item.curriculum_version_id=curriculum.id
on conflict(question_item_id,version_number) do nothing;

